module npu_controller(input wire clk,input wire rst,input wire start,output reg busy,output reg done,output reg [9:0] feature_index,output reg [1:0] class_group); reg [10:0] count; always @(posedge clk) begin if(rst) begin busy<=0;done<=0;feature_index<=0;class_group<=0;count<=0;end else begin done<=0; if(start&&!busy) begin busy<=1;feature_index<=0;class_group<=0;count<=0;end else if(busy) begin if(count==783) begin count<=0;feature_index<=0;if(class_group==2) begin busy<=0;done<=1;end else class_group<=class_group+1;end else begin count<=count+1;feature_index<=feature_index+1;end end end end endmodule
